fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Since the input is guaranteed non-empty, n > 0
    x.iter()
     .enumerate()
     .map(|(i, _)| {
         if i == 0 || i == n - 1 {
             0.5
         } else {
             1.0
         }
     })
     .collect()
}

